# PRINCE ALEX DIGITAL HMS - Emoji Removal Script
# Uses Unicode code points to avoid encoding issues
$ErrorActionPreference = "Stop"

# Helper to convert Unicode code point to string (handles supplementary chars)
function Get-Emoji([int]$codePoint) {
    return [char]::ConvertFromUtf32($codePoint)
}

# Emoji to icon name mapping using Unicode code points
$emojiMap = @{
    (Get-Emoji 0x1F4CA) = "dashboard"      # 📊
    (Get-Emoji 0x1F4C8) = "reports"        # 📈
    (Get-Emoji 0x1F4B0) = "money"          # 💰
    (Get-Emoji 0x1F4C5) = "appointments"   # 📅
    (Get-Emoji 0x1F465) = "users"          # 👥
    (Get-Emoji 0x1F3E8) = "admissions"     # 🏨
    (Get-Emoji 0x1F3E5) = "hospitals"      # 🏥
    ((Get-Emoji 0x1F6CF) + (Get-Emoji 0xFE0F)) = "beds"  # 🛏️
    (Get-Emoji 0x1F52C) = "laboratory"     # 🔬
    (Get-Emoji 0x1F48A) = "pharmacy"       # 💊
    (Get-Emoji 0x1F9FE) = "invoices"       # 🧾
    (Get-Emoji 0x1F514) = "bell"           # 🔔
    ((Get-Emoji 0x26A0) + (Get-Emoji 0xFE0F)) = "warning"  # ⚠️
    ((Get-Emoji 0x2699) + (Get-Emoji 0xFE0F)) = "settings" # ⚙️
