    (Get-Emoji 0x1F4CB) = "lab-orders"     # 📋
    (Get-Emoji 0x1F4C4) = "receipts"       # 📄
    (Get-Emoji 0x1F4E6) = "inventory"      # 📦
    (Get-Emoji 0x1F3ED) = "suppliers"      # 🏭
    (Get-Emoji 0x1F6D2) = "purchase-orders" # 🛒
    ((Get-Emoji 0x1F3D6) + (Get-Emoji 0xFE0F)) = "leave"   # 🏖️
    (Get-Emoji 0x1F4DC) = "audit-logs"     # 📜
    (Get-Emoji 0x1F48E) = "plans"          # 💎
    ((Get-Emoji 0x1F321) + (Get-Emoji 0xFE0F)) = "vitals"  # 🌡️
