    (Get-Emoji 0x1F3E2) = "wards"          # 🏢
    (Get-Emoji 0x1F489) = "medicines"      # 💉
    (Get-Emoji 0x1F4DD) = "prescriptions"  # 📝
    ((Get-Emoji 0x1F468) + (Get-Emoji 0x200D) + (Get-Emoji 0x2695) + (Get-Emoji 0xFE0F)) = "staff"  # 👨‍⚕️
    (Get-Emoji 0x1F525) = "firebase"       # 🔥
    (Get-Emoji 0x1F3A8) = "design"         # 🎨
    (Get-Emoji 0x26A1) = "zap"             # ⚡
    (Get-Emoji 0x2753) = "help"            # ❓
    ((Get-Emoji 0x270F) + (Get-Emoji 0xFE0F)) = "edit"     # ✏️
    (Get-Emoji 0x2795) = "plus"            # ➕
    (Get-Emoji 0x2705) = "check"           # ✅
    (Get-Emoji 0x2715) = "close"           # ✕
    (Get-Emoji 0x2190) = "back"            # ←
    (Get-Emoji 0x1F50D) = "search"         # 🔍
    (Get-Emoji 0x1F504) = "refresh"        # 🔄
    (Get-Emoji 0x23F3) = "clock"           # ⏳
}

