$root = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)
$htmlFiles = Get-ChildItem -Path $root -Filter "*.html" -Recurse | Where-Object { $_.FullName -notmatch "node_modules" }

$totalCount = 0
$changedFiles = @()

foreach ($file in $htmlFiles) {
    $content = [System.IO.File]::ReadAllText($file.FullName, [System.Text.Encoding]::UTF8)
    $original = $content
    $fileCount = 0

    foreach ($emoji in $emojiMap.Keys) {
        if ($content.Contains($emoji)) {
            $iconName = $emojiMap[$emoji]
            $svg = Get-SvgIcon $iconName
            $count = ([regex]::Matches($content, [regex]::Escape($emoji))).Count
            $fileCount += $count
            $content = $content.Replace($emoji, $svg)
        }
    }

    if ($content -ne $original) {
        [System.IO.File]::WriteAllText($file.FullName, $content, [System.Text.Encoding]::UTF8)
        $totalCount += $fileCount
        $changedFiles += "$($file.Name): $fileCount"
    }
}

Write-Host "Total emojis replaced: $totalCount"
Write-Host "Files changed:"
$changedFiles | ForEach-Object { Write-Host "  $_" }